"""AQS-BLD-013 equipment structural loads per level (X-BLD-02, A-M-184). For every placed unit (placement seed and study):
empty weight = steel from the unit design where the graph has it (gas receivers), else envelope volume x 150 kg/m3 equipment density (storage tanks 40 kg/m3, PV array 17 kg/m2 of roof);
operating = empty + liquid at SG 1.25 (hold-up volume of A-M-182 where stated, else half the envelope for a unit with liquid inflow);
test = empty + envelope full of water for liquid units (fill or hydro test). Point loads summed per level and per level footprint,
with the ASCE7_22 2.3.1 LRFD combination 1.2 D + 1.6 L taking the empty weight as D and the operating liquid as L;
the test case is reported unfactored. Run: python3 docs-authority/_struct_loads.py"""
import json, os, re, sys, collections
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); os.chdir(R); sys.path.insert(0, R)
from flow_graph.param import drivers as DR, site as SITE
d = DR.load(); RHO_EQ = DR.val(d, 'struct_equip_density_kg_m3'); FILL = DR.val(d, 'struct_op_fill'); SG = DR.val(d, 'atm_design_sg')
g = json.load(open('flow_graph/plant_flow_graph.json')); N = {n['unit_id']: n for n in g['nodes']}
liq_in = {e['to_unit_id'] for e in g['edges'] if e['presence'] == 'present' and e.get('phase') == 'L' and (e['rate']['value'] or 0) > 0}
rows = []
_U = json.load(open('flow_graph/placement_seed.json'))['units'] + json.load(open('flow_graph/placement_study.json'))['units']
_have = {u['unit_id'].split('/')[0] for u in _U}; _rep = json.load(open('flow_graph/placement_report.json')); _ph = []; _envs = []
from flow_graph.param import unit_envelopes as UE
for _r in [r for k in ('moves', 'create_moves', 'apply_moves') for r in _rep.get(k, [])]:   # units placed only by report moves (block-sized boxes): take the graph size
    b = _r['unit_id']; zz = ((N.get(b) or {}).get('params') or {}).get('size_mm')
    if b in _have or not _r.get('level') or (N.get(b) or {}).get('class') in ('header', 'building', 'dock', 'boundary'): continue
    pp = (N.get(b) or {}).get('params') or {}; ds_ = pp.get('design') or {}; vt = (pp.get('relief_basis') or {}).get('V_tk_m3') or 0
    _m = re.search(r'= ([0-9.]+) m3', (pp.get('relief_basis') or {}).get('design_case') or ''); vt = vt or (float(_m.group(1)) if _m else 0)
    if not (zz and len(zz) >= 3) and ds_.get('D_mm') and ds_.get('H_mm'): zz = [ds_['D_mm'], ds_['D_mm'], ds_['H_mm']]
    if not (zz and len(zz) >= 3) and vt > 0: Dm = (4*vt/(3.1416*DR.val(d, 'atm_HD')))**(1/3)*1000; zz = [Dm, Dm, Dm*DR.val(d, 'atm_HD')]
    if not (zz and len(zz) >= 3):
        zz, _why = UE.size(b, N.get(b), sum((e['rate']['value'] or 0) for e in g['edges'] if e['to_unit_id'] == b and e['presence'] == 'present' and e['rate'].get('unit') == 'kg/d'))
        if zz: _envs.append((b, zz, _why))
    if zz and len(zz) >= 3: _U.append(dict(unit_id=b, level=_r['level'], size_mm=zz[:3], _rep=1)); _have.add(b)
    else: _ph.append(b)
for u in _U:
    z = u.get('size_mm'); lv = u.get('level')
    if not (z and len(z) >= 3 and lv): continue
    base = u['unit_id'].split('/')[0]; n = N.get(base); p = (n or {}).get('params') or {}
    V = z[0]*z[1]*z[2]*1e-9; ds = p.get('design') or {}
    nrow = sum(1 for x in json.load(open('flow_graph/placement_study.json'))['units'] if x['unit_id'].split('/')[0] == base) or 1 if '/' in u['unit_id'] else 1
    empty = (ds.get('steel_kg')/nrow if ds.get('steel_kg') else z[0]*z[1]*1e-6*DR.val(d, 'struct_pv_kg_m2') if (n or {}).get('class') == 'pv' else V*(DR.val(d, 'struct_tank_kg_m3') if (n or {}).get('class') in ('tank', 'cut_tank') else RHO_EQ))
    m = re.search(r'= ([0-9.]+) m3', ((p.get('relief_basis') or {}).get('design_case') or ''))
    wet = base in liq_in or (n or {}).get('class') in ('tank', 'cut_tank')
    liq = (float(m.group(1))/nrow if m else V*FILL)*SG*1000 if wet else 0.0
    test = V*1000 if wet else 0.0
    rows.append((u['unit_id'], lv, empty, empty + liq, empty + test, z[0]*z[1]*1e-6))
sys.path.insert(0, os.path.join(R, 'models/freecad')); import params as FP     # Q-009 water tower: reservoir levels (AQS-BLD-014)
for i in range(FP.HYDRO_RES_LEVELS):
    a = FP.HYDRO['area_m2']; w = a*FP.HYDRO['depth_per_level_m']*1000; e = a*FP.HYDRO_RES_CLEAR/1000*DR.val(d, 'struct_tank_kg_m3')
    rows.append((f'HYDRO_RES_R{i+1}', f'R{i+1}', e, e + w, e + w, a))
L = collections.defaultdict(lambda: [0, 0, 0, 0, 0])
for r in rows:
    a = L[r[1]]; a[0] += r[2]; a[1] += r[3]; a[2] += r[4]; a[3] += r[5]; a[4] += 1
kN = lambda kg: kg*SITE.g()/1000
_nrep = sum(1 for u in _U if u.get("_rep")); _unl = ', '.join(sorted(x for x in _ph if (N.get(x) or {}).get('class') != 'hab')) or 'none'
md = ['# Equipment structural loads', '', 'Document number: AQS-BLD-013', 'Revision: B', 'Date: 2026-10-29',
      'Generated by `docs-authority/_struct_loads.py` from the unit placement and the plant graph. Do not edit by hand; change the generator and run `python3 -m flow_graph.param.regen`.', '',
      '| Rev | Description | Date |', '|---|---|---|',
      '| A | First issue: equipment loads per level for task X-BLD-02 | 2026-10-16 |',
      '| B | Rewritten to the style guide: purpose, method and table titles added; the description of the load combination corrected to match the calculation | 2026-10-29 |', '',
      '## 1. Purpose and scope', '',
      'This page gives the weight of the process equipment on each level of the building, for the frame check (X-BLD-01, AQS-BLD-016) and the foundation check (X-BLD-03, AQS-BLD-017). It covers equipment and the liquid it holds. Floor and roof live loads from people, storage and snow are not included here; the frame and foundation checks add them. Every value is a study value based on assumption A-M-184.', '',
      '## 2. Method', '',
      'Three load cases are calculated for every placed unit.', '',
      f'- The empty case is the steel mass from the unit design where the graph has one (the gas receivers). Otherwise it is the envelope volume times an equipment density of {RHO_EQ:.0f} kg/m³ (driver `struct_equip_density_kg_m3`), with separate densities for storage tanks (`struct_tank_kg_m3`) and for the photovoltaic array per square metre of roof (`struct_pv_kg_m2`).',
      f'- The operating case adds the liquid the unit holds, at a specific gravity (SG) of {SG} (driver `atm_design_sg`). The liquid volume is the hold-up volume where the graph states one; otherwise it is {FILL*100:.0f} % of the envelope (driver `struct_op_fill`) for a unit that receives liquid.',
      '- The test case fills the envelope of every liquid unit with water, as for a fill or hydrostatic test.', '',
      'The factored load uses the load and resistance factor design (LRFD) combination 1.2 D + 1.6 L of ASCE 7-22 section 2.3.1. The empty weight is the dead load D. The liquid of the operating case is taken as the live load L, because it varies and the larger factor is the conservative choice. Loads are converted from mass with the gravity of the site profile.', '',
      'Table 2.1 gives the totals for each level. The bearing pressure in the table is the operating load divided by the summed footprint of the units on that level.', '',
      'Table 2.1. Equipment loads per level', '',
      '| Level | Units | Footprint (m²) | Empty (kN) | Operating (kN) | Test (kN) | Operating pressure on footprint (kPa) | 1.2 D + 1.6 L, operating (kN) |', '|---|---|---|---|---|---|---|---|']
for lv in sorted(L):
    a = L[lv]; md.append(f'| {lv} | {a[4]} | {a[3]:.1f} | {kN(a[0]):.0f} | {kN(a[1]):.0f} | {kN(a[2]):.0f} | {kN(a[1])/a[3]:.1f} | {1.2*kN(a[0]) + 1.6*kN(a[1]-a[0]):.0f} |')
md += ['', '## 3. Heaviest units', '', 'Table 3.1 lists the heaviest units, ranked by their test case load.', '', 'Table 3.1. Heaviest units by test case load', '', '| Unit | Level | Empty (kN) | Operating (kN) | Test (kN) |', '|---|---|---|---|---|']
md += [f'| {r[0]} | {r[1]} | {kN(r[2]):.1f} | {kN(r[3]):.1f} | {kN(r[4]):.1f} |' for r in sorted(rows, key=lambda r: -r[4])[:15]]
md += ['', '## 4. Envelopes sized from need', '', 'Some units are placed by the placement report but have no size in the graph. Where the unit class has a sizing rule (assumption A-M-199), the envelope is sized from the unit duty and loaded as in section 2. Table 4.1 lists those envelopes.', '', 'Table 4.1. Envelopes sized from need', '', '| Unit | Length × width × height (mm) | Basis |', '|---|---|---|'] + [f'| {b} | {z[0]:.0f} × {z[1]:.0f} × {z[2]:.0f} | {w} |' for b, z, w in _envs]
md += ['', f'Units placed only by the placement report are loaded at their graph size ({_nrep} rows). Units with no graph size and no sizing rule are not loaded: {_unl}. HABITATION is a room and is carried as floor live load under ASCE 7-22 Table 4.3-1, not as equipment.']
json.dump([dict(unit=r[0], level=r[1], empty_kg=round(r[2], 1), op_kg=round(r[3], 1), test_kg=round(r[4], 1), foot_m2=round(r[5], 3)) for r in rows], open('docs-authority/inventory/STRUCT_ROWS.json', 'w'), indent=0)
open('docs-authority/STRUCT_LOADS.md', 'w').write('\n'.join(md) + '\n'); print({k: [round(kN(x)) for x in v[:3]] for k, v in L.items()})
